 function simField(key,label,help=''){const [min,max,integer]=S.limits[key],currency=label.includes('R$');return `<label class="field">${label}<input type="${currency?'text':'number'}" ${currency?'inputmode="decimal" data-currency="true"':''} name="${key}" data-param="${key}" value="${currency?brNumber.format(params[key]):params[key]}" ${currency?'':`min="${min}" max="${max}" step="${integer?'1':'any'}"`}>${help?`<small>${help}</small>`:''}</label>`;}
 function simRentField(){return `<div class="sim-rent-entry">${select('rentPeriod','Você cobra o aluguel por',rentPeriod,[['weekly','Semana'],['monthly','Mês']],'data-rent-period="true"')}${input('weekly',rentPeriod==='monthly'?'Valor do aluguel por mês · R$':'Valor do aluguel por semana · R$',rentPeriod==='monthly'?S.round(params.weekly*52/12):params.weekly,'type="number" data-param="weekly" min="0" step="any" required')}</div>`;}
 const simExtraOptions=[
  ['setup','Compra · Preparação por carro · R$'],['financingFees','Compra · Tarifas de financiamento · R$'],['stockCapital','Loja · Kit inicial por carro · R$'],['centralStockCapital','Loja · Estoque central inicial · R$'],
  ['kmPerDay','Uso · Km por dia alugado'],['energyPriceKWh','Recarga · Preço por kWh · R$'],['consumptionKWh100Km','Recarga · Consumo kWh/100 km'],['chargingLossPct','Recarga · Perdas · %'],['companyChargePct','Recarga · Parte paga pela locadora · %'],
  ['maintenanceKm','Carro · Manutenção por km · R$'],['tiresKm','Carro · Pneus por km · R$'],['other','Carro · Outros custos mensais · R$'],['staffThreshold','Empresa · Equipe a partir de quantos carros'],['staffCost','Empresa · Custo mensal da equipe · R$'],
  ['revenueTaxPct','Tributos · Sobre faturamento · %'],['cogsPct','Loja · Custo da mercadoria · %'],['storeRewardBasis','Loja · Modelo de benefício'],['commissionPct','Loja · Comissão da comparação antiga · %'],['driverProfitPct','Loja · Margem para motorista · %'],['paymentFeePct','Loja · Taxa de pagamento · %'],['storeLossPct','Loja · Perdas · %'],
  ['oneOffContribution','Aporte pontual · R$'],['contributionMonth','Mês do aporte pontual'],['annualRentIncrease','Reajuste anual do aluguel · %'],['annualCostInflation','Inflação anual dos custos · %'],['startYear','Ano inicial'],['startMonth','Mês inicial']
 ];
 function simExtraForm(key='setup'){const selected=simExtraOptions.find(([id])=>id===key)||simExtraOptions[0],label=selected[1];return `<form id="sim-extra-form">${select('key','Qual premissa quer ajustar?',selected[0],simExtraOptions.map(([id,name])=>[id,name]),'data-sim-extra-key="true"')}${selected[0]==='storeRewardBasis'?select('value',label,params.storeRewardBasis,[['margin','Lucro da loja para o motorista'],['gross','Comissão sobre venda · comparação antiga']]):input('value',label,params[selected[0]],`type="number" step="any" required`)}<p class="caption">O valor atual já está considerado na projeção. Coloque zero para retirar um custo quando a premissa permitir. As regras do piloto, como a margem da loja para o motorista, permanecem explícitas.</p><div class="form-actions"><button type="submit" class="btn primary">Aplicar à simulação</button></div></form>`;}
 function growthForm(){const quote=S.purchaseQuote(params,'growth');return simSelect('reinvest','Comprar carros automaticamente?',[['false','Não · manter caixa'],['true','Sim · quando as condições forem atendidas']])+simField('purchaseTriggerCash','Comprar quando o caixa chegar a · R$','Conferido no fechamento de cada mês, antes da compra. Zero significa comprar assim que o custo e a reserva couberem.')+simField('growthPrice','Preço diferente para os próximos carros · R$','Zero usa o mesmo preço do primeiro carro.')+simSelect('growthPurchaseMode','Como comprar os próximos carros',[['same','Mesmas condições do primeiro carro'],['cash','À vista'],['financed','Financiado · condições próprias']])+ (params.growthPurchaseMode==='financed'?input('growthDownAmount','Entrada por próximo carro · R$',S.round(quote.price*params.growthDownPct/100),'type="number" min="0" step="any" data-growth-entry="true"')+input('growthLoanAmount','Financiado por próximo carro · R$',quote.debt,'type="number" readonly data-growth-loan-value="true"')+simField('growthTerm','Prazo do próximo carro · meses')+simField('growthMonthlyRate','Juros do próximo carro · % ao mês'):'')+`<p class="caption">Sem preço diferente, vale o preço do primeiro carro. Preparação e kit seguem as premissas acima. A regra vale apenas para carros adicionais, até a meta de frota.</p>`;}
 function simSelect(key,label,options){return select(key,label,String(params[key]),options,`data-param="${key}" ${['growthPurchaseMode','financed'].includes(key)?'data-purchase-mode="true"':''}`);}
 function simCard(number,title,body){return `<section class="panel form-card"><div class="panel-head"><h2>${title}</h2><span>${number}</span></div><div class="fields">${body}</div></section>`;}
 function marketReference(){return `<section class="panel sim-market"><div class="panel-head"><div><h2>Referências para frota elétrica · Maringá/PR</h2><p>O modelo ainda não foi escolhido. Os valores do cenário são hipóteses editáveis.</p></div>${btn('Aplicar revisão programada de referência','apply-market-reference')}</div><div class="grid3"><div>${row('BYD Dolphin Mini · revisões programadas',cash(8576)+' até 200 mil km','Equivale a cerca de R$ 0,04288/km; não inclui pneus, recarga ou reparos.')}</div><div>${row('Preço do carro',money(params.price),'Hipótese arredondada; peça cotação atual do modelo escolhido.')}</div><div>${row('Recarga no piloto','Motorista paga','Preço efetivo por kWh varia por ponto e tarifa; não é despesa da locadora por padrão.')}</div></div><p class="caption">Fontes: <a href="https://www.byd.com/br/plano-de-manutencao-2026" target="_blank" rel="noopener noreferrer">BYD · plano de manutenção</a> · <a href="https://www.copel.com/site/copel-distribuicao/tarifas-de-energia-eletrica/" target="_blank" rel="noopener noreferrer">Copel · tarifas</a> · <a href="https://www.gov.br/inmetro/pt-br/assuntos/avaliacao-da-conformidade/programa-brasileiro-de-etiquetagem/tabelas-de-eficiencia-energetica/veiculos-automotivos-pbe-veicular" target="_blank" rel="noopener noreferrer">Inmetro · eficiência</a>. Solicite cotação do carro, seguro, recarga e manual do modelo escolhido antes de decidir.</p></section>`;}

 function decisionContext(){const stress=P.decisionStress(params),breakEven=P.breakEvenWeekly(params);return `${section('A decisão resiste a um mês ruim?','Sensibilidade determinística com o mesmo motor financeiro; não é previsão de mercado.')}<div class="stats">${stat('Aluguel semanal de equilíbrio',breakEven===null?'Não calculável':cash(breakEven),'Para o fluxo do primeiro mês após custos e parcela; não inclui recuperar o investimento')}${stat('Aluguel informado',cash(params.weekly),'Preço que você pretende cobrar; valide com a oferta local e o motorista')}</div>${table(['Cenário','Primeiro mês após custos e parcela','Menor folga sobre a reserva','Caixa final','Patrimônio final'],stress.map(c=>`<tr><td>${esc(c.name)}${c.acquired?'':' · compra não cabe'}</td><td>${cash(c.firstCashAfterDebt)}</td><td>${cash(c.minAvailable)}</td><td>${cash(c.endingCash)}</td><td>${cash(c.endingEquity)}</td></tr>`).join(''))}<p class="caption">São choques isolados, não probabilidades. Se a compra inicial não couber, os resultados não representam uma frota operando. A folga abaixo de zero indica quebra da reserva; patrimônio inclui valor estimado do carro e não é dinheiro disponível.</p>`;}
 function simulator(){return heading('SIMULAR ANTES DE EXECUTAR','Entenda sua conta primeiro.','Comece com o essencial. Veja primeiro quanto entra, cada custo e o que falta; ajuste outras premissas quando precisar.',btn('Salvar cenário','save-scenario')+btn('Exportar fluxo','export-flow')+btn('Usar como plano de referência','freeze','primary'))+`<div class="filter-row"><div><strong>${esc(scenarioName)}</strong><p class="caption">Rascunho independente de ${esc(baseline.id)} · mudanças recalculam automaticamente.</p></div><div class="actions">${btn('Meus cenários','scenarios')}<span id="sim-status" class="sim-saved">${isQA?'Sessão isolada de teste':'Salvamento local'}</span></div></div><div id="sim-safety" hidden>${safetyStrip()}</div><div id="sim-capacity" class="notice gap">Com esse capital, cabem até <strong>${report.capacityNow} carro(s)</strong> na aquisição inicial, preservando a reserva e os custos de preparação. Sua configuração pede ${params.initialFleet}.</div><form id="sim-form"><div class="grid3 sim-form">${simCard('01','Seu capital',simField('initialCapital','Capital disponível · R$')+simField('reserveFixed','Reserva de segurança · R$')+simField('companySetup','Abertura da empresa · R$')+simField('reservePerCar','Reserva adicional por carro · R$')+simField('initialFleet','Carros iniciais')+simField('targetFleet','Objetivo de frota'))}${simCard('02','Compra e financiamento',simSelect('financed','Forma de aquisição',[['true','Financiado · Price'],['false','À vista']])+simField('price','Preço do carro · R$')+input('downAmount','Entrada por carro · R$',S.round(params.financed?params.price*params.downPct/100:params.price),'type="number" min="0" step="any" data-entry="true"')+input('loanAmount','Valor financiado · R$',S.round(params.financed?params.price*(1-params.downPct/100):0),'type="number" readonly data-loan-value="true"')+simField('term','Prazo · meses')+simField('monthlyRate','Juros · % ao mês'))}${simCard('03','Receita e utilização',simRentField()+simField('occupancy','Ocupação esperada · %')+simField('lossPct','Perda de recebimento · %')+simField('stoppedDays','Dias parados por mês')+simField('storeDaily','Vendas da loja por dia alugado · R$')+simField('horizon','Projetar por · meses'))}${simCard('04','Custo de cada carro',simField('insurance','Seguro mensal · R$')+simField('maintenanceMonthly','Reserva mensal de manutenção EV · R$')+simField('annualTax','IPVA anual · R$')+simField('annualLicense','Licenciamento anual · R$')+simField('tracker','Rastreador mensal · R$')+simField('washing','Limpeza mensal · R$'))}${simCard('05','Regra para comprar o próximo carro',growthForm())}<details class="sim-form-more"><summary>Ajustar crescimento e contas da empresa</summary><div class="grid2">${simCard('06','Outras regras de crescimento',simField('maxPurchasesPerMonth','Máximo de compras por mês')+simSelect('amortStrategy','Amortização extraordinária',[['off','Nunca'],['afterGoal','Caixa livre após a meta'],['monthly','Todo mês'],['sixMonths','A cada 6 meses'],['once','Evento escolhido']])+simField('extraAmort','Valor por evento · R$')+simField('extraMonth','Mês do evento único')+simSelect('priority','Primeiro usar o caixa para',[['growth','Comprar carro'],['debt','Amortizar dívida']]))}${simCard('07','Empresa e patrimônio',simField('admin','Administração / contador · R$ por mês')+simField('cashYieldAnnual','Rendimento do caixa · % ao ano')+simField('depreciationPct','Depreciação · % ao mês')+simField('profitTaxPct','IR sobre lucro positivo · %')+simField('monthlyContribution','Aporte mensal · R$')+simField('ownerDrawPct','Retirar do fluxo livre · %'))}</div></details></div><div class="sim-add-box"><strong>Quer incluir ou mudar outro custo?</strong><p>As despesas que já entram na conta aparecem no resumo logo abaixo. Adicione ou ajuste uma premissa de cada vez.</p>${btn('Adicionar ou ajustar uma premissa','sim-adjust-cost')}</div><div id="sim-error" class="form-error" role="alert" hidden></div></form><div id="sim-results">${simulatorResults()}</div>`;}
 function safetyStrip(){const d=report.decision;return `<div class="safety-strip"><div><small>OCUPAÇÃO PARA EQUILIBRAR O CAIXA</small><strong>${pct(d.occupancyMin)}</strong></div><div><small>ALUGUEL SEMANAL DE EQUILÍBRIO</small><strong>${money(d.weeklyMin)}</strong></div><div><small>PRIMEIRO MÊS ABAIXO DA RESERVA</small><strong>${d.reserveBreach===null?'Não ocorre':'Mês '+d.reserveBreach}</strong></div><div><small>PRIMEIRO CAIXA NEGATIVO</small><strong>${d.negative===null?'Não ocorre':'Mês '+d.negative}</strong></div></div>`;}
 function monthlyClarity(){
  const m=report.result.months[0],details=P.monthlyExplanation(params,m),earned=details.items.filter(([,value])=>value>0).reduce((sum,[,value])=>sum+value,0),spent=-details.items.filter(([,value])=>value<0).reduce((sum,[,value])=>sum+value,0),weekly=P.breakEvenWeekly(params),initialCars=report.result.initial.cars.length;
  const group=(title,from,to)=>{const lines=details.items.slice(from,to).filter(([,value])=>Math.abs(value)>0.000001);return lines.length?`<div class="sim-break-group"><h3>${title}</h3>${lines.map(([label,value])=>row(esc(label),cash(value))).join('')}</div>`:'';};
  const amount=rentPeriod==='monthly'?money(params.weekly*52/12)+' por mês':money(params.weekly)+' por semana',equivalent=rentPeriod==='monthly'?money(params.weekly)+' por semana':money(params.weekly*52/12)+' por mês';
  const balance=details.net<0?`Faltam ${money(details.gap)} no primeiro mês para a operação pagar seus custos e a parcela.`:`Sobram ${money(details.net)} no primeiro mês depois dos custos e da parcela.`;
  const priceHint=weekly===null?'Antes de avaliar o aluguel de equilíbrio, ajuste o capital para que o carro possa ser comprado.':details.net<0?`Com as mesmas hipóteses, o aluguel de equilíbrio é cerca de ${money(weekly*52/12)} por mês (${money(weekly)} por semana). Isso cobre a operação e a parcela, mas não recupera a entrada do carro.`:'A operação cobre seus custos neste mês. Isso ainda não significa que a entrada do carro foi recuperada.';
  const upfront=initialCars?`<details class="sim-startup"><summary>Ver dinheiro necessário para começar, separado do mês</summary>${row('Entrada ou compra à vista por carro',money(params.financed?params.price*params.downPct/100:params.price))}${row('Preparação por carro',money(params.setup))}${params.financed?row('Tarifas do financiamento por carro',money(params.financingFees)):''}${row('Kit inicial por carro',money(params.stockCapital))}${row('Abertura da empresa',money(params.companySetup))}${row('Estoque central',money(params.centralStockCapital))}${row('Total desembolsado no início',money(params.companySetup+params.centralStockCapital+initialCars*report.result.purchaseCash),'',true)}${row('Reserva que precisa permanecer no caixa',money(params.reserveFixed+initialCars*params.reservePerCar))}<p class="caption">Entrada e estoque usam caixa na compra. Reserva não é despesa. Esses valores não são repetidos como custo mensal.</p></details>`:'';
  return `<section class="panel sim-clarity ${details.net<0?'sim-clarity-negative':''}"><div class="panel-head"><div><h2>Por que a conta ${details.net<0?'não fecha':'fecha'}?</h2><p>Primeiro mês · ${esc(m.label)} · ${initialCars} carro(s) comprados no início</p></div></div><div class="sim-balance"><span>${details.net<0?'Falta no mês':'Sobra no mês'}</span><strong>${money(Math.abs(details.net))}</strong><p>${balance}</p></div><p class="sim-rent-note">Você informou <strong>${amount}</strong> (equivale a cerca de ${equivalent}). O modelo considera ${num(details.rentableDays)} dias alugados, após ${num(params.stoppedDays)} dia(s) parado(s) e ${num(params.occupancy)}% de ocupação. Dos ${money(m.rentalBilled)} previstos de aluguel, ${money(m.rentalLoss)} podem não ser recebidos; entram ${money(m.rentalReceived)}.</p><div class="sim-totals">${row('Entradas do mês',money(earned))}${row('Perdas, despesas e parcela',money(spent))}${row('Saldo da operação',money(details.net),'',true)}</div><p class="sim-price-hint">${priceHint}</p><details class="sim-cost-list" open><summary>Ver de onde sai cada real</summary>${group('Aluguel e vendas',0,3)}${group('Loja e benefício do motorista',3,7)}${group('Carro: custos fixos',7,13)}${group('Empresa e equipe',13,15)}${group('Manutenção, pneus e recarga',15,20)}${group('Tributos',20,22)}${group('Financiamento e rendimento',22,25)}<p class="caption">Tributos sobre faturamento incidem sobre aluguel previsto e vendas da loja. Juros e principal compõem a parcela; depreciação afeta o lucro, mas não sai do caixa. Valores exibidos são arredondados a centavos.</p></details>${upfront}</section>`;
 }
 function growthSummary(){
  const result=report.result,quote=result.growthQuote,rule=result.months[0]?.purchaseRule,buys=result.events.filter(event=>event.type==='purchase'&&event.month>0),first=buys[0];
  const reason=!params.reinvest?'A compra automática está desligada. Ative a regra no campo acima para testar.':result.initial.cars.length>=params.targetFleet?'A frota inicial já atingiu a meta. Aumente o objetivo de frota para estudar novas compras.':rule?.status==='threshold'?`No primeiro mês, faltam ${money(Math.max(0,params.purchaseTriggerCash-rule.cashAtDecision))} para alcançar o gatilho de caixa.`:rule?.status==='reserve'?`No primeiro mês, faltam ${money(Math.max(0,rule.requiredCash-rule.cashAtDecision))} para pagar o carro e manter a reserva.`:first?`Primeira compra adicional simulada no fechamento de ${S.label(params,first.month)}.`:'Nenhuma compra adicional coube no horizonte informado.';
  const mode=quote.mode==='cash'?'À vista':'Financiado';
  return `<section class="panel sim-growth-result"><div class="panel-head"><div><h2>Quando entra o próximo carro?</h2><p>A regra é avaliada no fechamento de cada mês. O carro novo começa a gerar aluguel no mês seguinte.</p></div>${tag(params.reinvest?'Regra ativa':'Regra desligada',params.reinvest?'green':'amber')}</div><p class="notice">${reason}</p><div class="grid3">${row('Gatilho de caixa antes da compra',money(params.purchaseTriggerCash))}${row('Custo em caixa do próximo carro',money(quote.cashCost))}${row('Preço do próximo carro',money(quote.price))}</div><div class="grid3 gap">${row('Entrada ou preço à vista',money(quote.entry))}${row('Nova dívida por carro',money(quote.debt))}${row('Nova parcela mensal',money(quote.installment))}</div><div class="grid2 gap">${row('Caixa na primeira decisão',money(rule?.cashAtDecision??0))}${row('Mínimo para comprar e preservar reserva',money(rule?.requiredCash??0))}</div><p class="caption">Forma escolhida: <strong>${mode}</strong>. Além de alcançar o gatilho, o caixa deve cobrir ${money(quote.cashCost)} e preservar a reserva fixa, a reserva por carro e obrigações existentes. A regra não usa caução nem crédito do motorista como capital livre. Compra simulada não é aquisição real.</p>${first?`<div class="sim-buy-timeline"><h3>Compras adicionais nesta projeção</h3>${buys.slice(0,12).map(event=>row(S.label(params,event.month)+' · '+event.id,money(event.amount)+' do caixa',`${event.mode==='cash'?'À vista':'Financiado'} · dívida nova ${money(event.newDebt)} · caixa após compra ${money(event.cashAfter)}`)).join('')}${buys.length>12?`<p class="caption">Mais ${buys.length-12} compra(s) no fluxo completo.</p>`:''}</div>`:''}</section>`;
 }
 function simulatorResults(){const r=report.result,d=report.decision,f=r.final,m=r.months[0],mid=r.months[Math.floor((r.months.length-1)/2)];return `${monthlyClarity()}${growthSummary()}<details class="sim-projection" ${projectionOpen?'open':''}><summary>Ver fluxo completo, gráficos e projeções</summary>${marketReference()}${safetyStrip()}${panel('Recarga no cenário',row('Energia comprada · primeiro mês',num(m.chargingKWh)+' kWh')+row('Custo do motorista · primeiro mês',money(m.chargingDriver),'Fora do caixa e resultado da locadora.')+row('Custo da locadora · primeiro mês',money(m.chargingCompany),'Incluído uma vez nas despesas operacionais.')+row('Quem paga',params.companyChargePct===0?'Motorista · 100%':params.companyChargePct+'% locadora / '+(100-params.companyChargePct)+'% motorista'))}${report.acquisitionGap>0?`<div class="notice amber gap"><strong>A compra inicial não cabe preservando a reserva.</strong> Você pediu ${params.initialFleet} carro(s), mas ${r.initial.cars.length} cabem. Faltam ${money(report.acquisitionGap)} para a configuração solicitada.</div>`:''}${decisionContext()}${section('O negócio em números','Primeiro mês operacional e posição no fim do horizonte, com bases identificadas.')}<div class="stats executive">${stat('Fluxo livre · primeiro mês',money(m.cashAfterDebt),'Após custos, tributos e parcela',true)}${stat('Lucro · primeiro mês',money(m.result),'Inclui juros e depreciação; principal não é despesa')}${stat('ROI · horizonte completo',pct(d.roi),'Lucro acumulado ÷ capital próprio aportado')}${stat('Recuperação econômica',d.resultPayback===null?'Além do horizonte':'Mês '+d.resultPayback,'Lucro acumulado alcança o aporte; não é saque')}${stat('Capital próprio aportado',money(f.capital),'Inicial + aportes do horizonte')}${stat('Caixa livre · primeiro mês',money(m.available),'Caixa de fechamento menos a reserva')}${stat('Patrimônio nos carros · final',money(f.assets-f.debt),'Valor estimado dos carros menos a dívida')}${stat('Retorno · primeiro mês',pct(report.monthReturnPct),'Lucro mensal ÷ capital aportado')}${stat('Valor da frota · final',money(f.assets),'Estimativa de depreciação, sem cotação')}${stat('Patrimônio total · final',money(f.equity),'Caixa + carros + kit estimado − dívida')}</div><div class="grid2">${panel('Quanto do seu dinheiro já se pagou?',row('Capital próprio aportado',money(f.capital))+row('Recuperação econômica pelo lucro',money(report.economicRecovered),'Lucro acumulado positivo limitado ao capital aportado.')+`<div class="progress" role="progressbar" aria-label="Recuperação econômica" aria-valuenow="${report.economicRecoveryPct??0}" aria-valuemin="0" aria-valuemax="100"><i style="width:${report.economicRecoveryPct??0}%"></i></div>`+row('Ainda falta recuperar economicamente',money(report.capitalNotEconomicallyRecovered))+row('Dinheiro efetivamente retirado',money(report.cashRecovered),'Retirada é fluxo ao proprietário; lucro retido permanece na empresa.'))}${panel('Amortização que acontece de verdade',row('Amortização extra no horizonte',money(r.totalExtra),'Somente o valor que coube após preservar a reserva.')+row('Juros pagos no horizonte',money(report.totalInterest))+row('Dívida ao final',money(f.debt))+row('Frota ao final',f.fleet+' de '+params.targetFleet+' carros',r.targetMonth===null?'Objetivo não atingido dentro do horizonte.':'Meta atingida no mês '+r.targetMonth)+row('Folga de parada · primeiro mês',d.daysMargin===null?'Sem base':num(d.daysMargin)+' dias','Equivalência de caixa mantidas as demais premissas.'))}</div>${section('Fluxo detalhado','Leia a conta antes do gráfico. Hoje → operação → dívida → resultado → caixa.',segments([['annual','Ano a ano'],['monthly','Mês a mês']],flowMode,'flow-mode'))}${flowTable()}${section('A evolução do negócio','Os mesmos valores do fluxo, vistos ao longo do tempo.')}<div class="grid2">${chart('sim-cashflow','Fluxo da operação, mês a mês',['Entradas','Despesas','Parcela','Lucro'],'Entradas incluem aluguel recebido e loja. Despesas excluem a parcela; juros e principal continuam discriminados na tabela.')}${chart('sim-assets','Quanto os carros valem e quanto ainda devem',['Valor dos carros','Dívida','Patrimônio nos carros'])}</div><div class="grid2 gap">${chart('sim-cash','Evolução do caixa e da reserva',['Caixa de fechamento','Reserva mínima'],'Compras e amortizações extraordinárias só acontecem quando preservam a reserva. A própria operação deficitária pode consumi-la.')}${chart('sim-equity','Patrimônio construído e capital próprio',['Patrimônio total','Capital aportado'])}</div><div class="gap">${chart('sim-fleet','Quando cada novo carro entra na frota',['Frota ao fim do mês'],'A compra aparece no fechamento; o carro só passa a gerar receita no mês seguinte.')}</div>${section('Patrimônio em três momentos','Caixa, ativos e dívida em posições comparáveis.')}<div class="grid3">${[['Hoje',report.initial],['Meio do caminho · '+mid.label,mid],['Fim do plano · '+f.label,f]].map(([label,pos])=>panel(label,row('Carros',String(pos.fleet))+row('Valor dos carros',money(pos.assets))+row('Saldo devedor',money(pos.debt))+row('Caixa',money(pos.cash))+row('Patrimônio total',money(pos.equity),'Inclui kit estimado.',true))).join('')}</div>${section('Amortizar ou comprar o próximo?','Mesmo capital, premissas e horizonte. Estratégias determinísticas, sem nota subjetiva de risco.')}${panel('Uso do capital',table(['Estratégia','Frota final','Juros totais','Caixa','Dívida','Patrimônio'],d.alternatives.map(a=>`<tr><td>${a.name}</td><td>${a.result.final.fleet}</td><td>${money(a.interest)}</td><td>${money(a.result.final.cash)}</td><td>${money(a.result.final.debt)}</td><td>${money(a.result.final.equity)}</td></tr>`).join(''))+'<p class="caption">“Amortizar” prioriza a dívida com '+money(params.extraAmort)+'/mês. “Comprar” reinveste sem extra. “Manter” não expande nem faz amortização extra.</p>')}${section('Comprar agora ou esperar?','Uma compra adicional. Todas as alternativas terminam no mesmo horizonte de 24 meses.')}<div class="grid3">${T.purchaseTiming(params).map(o=>panel(o.wait===0?'Comprar agora':'Esperar '+o.wait+' meses',tag(o.viable?'Entrada + reserva cabem':'Ainda não cabe',o.viable?'green':'amber')+row('Falta para entrada e reserva',money(o.gap))+row('Caixa no horizonte',money(o.cash))+row('Patrimônio no horizonte',money(o.equity),'Sem outras aquisições durante a comparação.'))).join('')}</div>${section('Linha do tempo completa','Todos os meses, sem trocar de tela. Clique no período para abrir a memória de cálculo.')}<div class="month-cards">${report.monthly.map(m=>`<section class="month-card ${m.purchases?'purchase':''}"><strong>${link(m.label+' · mês '+m.month,'month-detail',`data-month="${m.month}"`)}</strong>${m.purchases?tag('+'+m.purchases+' carro(s)','green'):''}${row('Entradas',money(m.income))}${row('Pagamentos',money(m.paid))}${row('Lucro',money(m.result))}${m.purchases?row('Compras',money(m.capex)):''}${row('Caixa final',money(m.cash))}${row('Frota',m.fleet+' carros')}</section>`).join('')}</div><details class="sim-advanced"><summary>Estudar venda e renovação do veículo</summary><p class="caption">Estudo especializado do legado: um carro hipotético, preço de venda informado, sem depreciação, loja ou tributos. Não representa venda real da frota.</p><div class="form-actions">${btn('Abrir estudo de renovação','renewal')}</div></details><div class="notice gap">${r.warnings.length?r.warnings.map(w=>esc(w)).join('<br>'):'Nenhum caixa negativo ou quebra de reserva no horizonte, sob as premissas informadas.'} Custos, tributos e valor dos ativos são estimativas de planejamento. Esta projeção não executa compras nem financiamentos.</div></details>`;}
 function flowTable(){const rows=[report.initial,...(flowMode==='annual'?report.annual:report.monthly)];return panel('Operação → financiamento → resultado → caixa',`<div class="table-wrap"><table class="flow-table"><thead><tr>${P.columns.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.map(m=>`<tr class="${m.month===0?'initial':m.available<0?'below':m.purchases?'purchase':''}">${P.columns.map(([key])=>`<td class="${key==='label'?'':'numeric'}">${key==='label'?(m.month===0?'Hoje · antes da operação':flowMode==='annual'?m.label+(m.monthsCount<12?' · '+m.monthsCount+' meses':''):link(m.label+' · M'+m.month,'month-detail',`data-month="${m.month}"`)):m[key]===null?'—':['fleet','purchases'].includes(key)?num(m[key]):cash(m[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">Tabela completa: role horizontalmente para conferir todas as colunas. Parcela = juros + amortização programada. Amortização total = programada + extra. Principal não é despesa; a depreciação reduz lucro, mas não sai do caixa. Entradas incluem vendas brutas da loja; despesas incluem mercadoria, comissão, taxas, perdas e tributos de faturamento. Ano parcial mostra quantos meses contém; caixa, frota e dívida são saldos finais, nunca soma de saldos.</p>`,btn('Exportar esta tabela','export-flow'));}
 function readSimulator(){const form=root.querySelector('#sim-form');if(!form)return;const next={...params};form.querySelectorAll('[data-param]').forEach(e=>{const key=e.dataset.param;next[key]=['financed','reinvest'].includes(key)?e.value==='true':['amortStrategy','priority','storeRewardBasis','growthPurchaseMode'].includes(key)?e.value:e.dataset.currency?key==='weekly'&&rentPeriod==='monthly'?parseMoney(e.value)*12/52:parseMoney(e.value):Number(e.value);});let entry=parseMoney(form.querySelector('[data-entry]').value);if(!next.financed){entry=next.price;form.querySelector('[data-entry]').value=brNumber.format(entry);}else if(!params.financed){entry=next.price*params.downPct/100;form.querySelector('[data-entry]').value=brNumber.format(entry);}const error=root.querySelector('#sim-error');try{if(!Number.isFinite(entry)||entry<0||entry>next.price)throw new RangeError('A entrada precisa ficar entre zero e o preço do carro.');next.downPct=next.financed&&next.price>0?entry/next.price*100:params.downPct;const growthEntry=form.querySelector('[data-growth-entry]');if(growthEntry&&next.growthPurchaseMode==='financed'){const amount=parseMoney(growthEntry.value);if(!Number.isFinite(amount)||amount<0||amount>S.purchaseQuote(next,'growth').price)throw new RangeError('A entrada do próximo carro precisa ficar entre zero e o preço.');next.growthDownPct=amount/S.purchaseQuote(next,'growth').price*100;}const valid=S.validate(next),nextReport=P.report(valid);params=valid;report=nextReport;revision=null;error.hidden=true;form.querySelector('[data-loan-value]').value=brNumber.format(S.round(params.financed?params.price-entry:0));const growthLoan=form.querySelector('[data-growth-loan-value]');if(growthLoan)growthLoan.value=brNumber.format(S.round(S.purchaseQuote(params,'growth').debt));updateSimulatorResults();const saved=persist(),status=root.querySelector('#sim-status');if(status)status.textContent=isQA?'Recalculado · sessão de teste':saved?'Salvo neste navegador':'Não foi possível salvar';}catch(err){error.hidden=false;error.textContent=err.message;}}
 function updateSimulatorResults(){const results=root.querySelector('#sim-results'),safety=root.querySelector('#sim-safety');if(!results)return;results.innerHTML=simulatorResults();safety.innerHTML=safetyStrip();root.querySelector('#sim-capacity').innerHTML=`Com esse capital, cabem até <strong>${report.capacityNow} carro(s)</strong> na aquisição inicial, preservando reserva e preparação. Sua configuração pede ${params.initialFleet}.`;drawCharts();}
 function simulatorAction(action,e){
  if(action==='apply-market-reference'){params=S.validate({...params,maintenanceKm:.04288});scenarioName='Elétrico · revisão programada de referência';revision=null;render();persist();toast('Somente a revisão programada por km foi aplicada. Cotação, pneus e demais custos continuam por validar.');return true;}
  if(action==='month-detail'){const m=report.result.months.find(m=>m.month===Number(e.dataset.month));open('Memória de cálculo · '+m.label,P.bridge(m).map(([label,value],i)=>row(label,cash(value),'',i===13)).join('')+row('Juros dentro da parcela',cash(m.interest))+row('Principal dentro da parcela',cash(m.scheduledPrincipal))+row('Depreciação sem saída de caixa',cash(m.depreciation))+row('Lucro líquido do mês',cash(m.result))+`<p class="caption">Diferença da identidade de caixa: ${cash(m.bridgeError)}. Todos os valores vêm do mesmo motor, sem recalcular na tela.</p>`);return true;}
  if(action==='sim-adjust-cost'){open('Ajustar uma premissa',simExtraForm());return true;}
  if(action==='save-scenario'){open('Salvar cenário independente',`<form id="scenario-form">${input('name','Nome do cenário',scenarioName,'required maxlength="100"')}<div class="form-actions"><button type="submit" class="btn primary">Preservar esta cópia</button></div></form>`);return true;}
  if(action==='scenarios'){open('Seus cenários',savedScenarios.length?table(['Cenário','Horizonte','Ações'],savedScenarios.map((s,i)=>`<tr><td>${esc(s.name)}<small>${esc(new Date(s.at).toLocaleString('pt-BR'))}</small></td><td>${s.params.horizon} meses</td><td>${btn('Carregar cópia','load-scenario','',`data-index="${i}"`)} ${btn('Excluir cópia','delete-scenario','',`data-index="${i}"`)}</td></tr>`).join('')):'<p class="caption">Use “Salvar cenário” para preservar uma cópia antes de testar outra hipótese.</p>');return true;}
  if(action==='load-scenario'){const s=savedScenarios[Number(e.dataset.index)];params=S.validate(structuredClone(s.params));scenarioName=s.name;page='simulator';mode='admin';close();render();persist();return true;}
  if(action==='delete-scenario'){savedScenarios.splice(Number(e.dataset.index),1);close();persist();toast('Cópia removida dos cenários locais.');return true;}
  if(action==='export-flow'){download('rodavolt-fluxo-'+(flowMode==='annual'?'anual':'mensal')+'.csv',P.csv([report.initial,...(flowMode==='annual'?report.annual:report.monthly)]),'text/csv;charset=utf-8');return true;}
  if(action==='renewal'){open('Estudar a renovação',`<form id="renewal-form"><div class="fields">${input('value','Valor estimado da venda · R$',55000,'type="number" min="0" step=".01" required')}${input('fee','Custos de venda · %',3,'type="number" min="0" max="100" step="any" required')}</div><p class="caption">Compara vender em até 12 datas trimestrais com manter até o final. Valor de venda é sua hipótese, sem cotação automática.</p><div class="form-actions"><button type="submit" class="btn primary">Comparar manter e vender</button></div></form>`);return true;}
  return false;
 }
 function simulatorSubmit(form,f){if(form.id==='sim-extra-form'){const key=String(f.get('key'));if(!simExtraOptions.some(([id])=>id===key))throw new RangeError('Premissa não encontrada.');const value=key==='storeRewardBasis'?String(f.get('value')):Number(f.get('value'));params=S.validate({...params,[key]:value});report=P.report(params);revision=null;close();render();persist();toast('Premissa aplicada. Confira a conta mensal.');return true;}if(form.id==='scenario-form'){const name=String(f.get('name')).trim();if(!name)throw new RangeError('Informe o nome do cenário.');scenarioName=name;savedScenarios.push({name,params:structuredClone(params),at:new Date().toISOString()});close();render();persist();toast('Cenário preservado. O plano de comparação não foi alterado.');return true;}
 if(form.id==='renewal-form'){const e=T.validateExpansion({...T.defaults().expansion,price:params.price,entry:params.financed?params.price*params.downPct/100:params.price,rate:params.monthlyRate,term:params.term,weekly:params.weekly,occupancy:params.occupancy,insurance:params.insurance,annualTax:params.annualTax,tracker:params.tracker,maintenance:params.maintenanceKm+params.tiresKm,km:params.kmPerDay*28,admin:params.admin,reserve:params.reserveFixed,horizon:params.horizon,saleValue:Number(f.get('value')),saleFee:Number(f.get('fee'))}),r=T.renewal(e);open('Manter ou vender · mesmo horizonte',`<div class="notice">Melhor entre as hipóteses: <strong>${r.best.mesVenda===null?'manter':'vender no mês '+r.best.mesVenda}</strong>. Patrimônio final de ${money(r.best.patrimonioFinalNoHorizonte)}.</div>`+table(['Venda','Caixa final','Dívida','Patrimônio','Capital reciclado','Frota'],r.porMomento.map(m=>`<tr><td>${m.mesVenda===null?'Manter':'Mês '+m.mesVenda}</td><td>${money(m.caixaFinal)}</td><td>${money(m.meses.at(-1).saldoDevedor)}</td><td>${money(m.patrimonioFinalNoHorizonte)}</td><td>${money(m.capitalReciclado)}</td><td>${m.frotaFinalUnidades}</td></tr>`).join(''))+`<p class="caption">Modelo especializado do legado: valor dos veículos constante, sem depreciação, loja ou tributos. Não compare diretamente com o patrimônio do modelo empresarial completo. Venda abaixo da dívida mostra a diferença negativa.</p>`);return true;}return false;}
